export const copyCatalog: Record<string, Record<Locale, string>> = {};
for (const row of rows) {
  const entry = {} as Record<Locale, string>;
  catalogLocales.forEach((locale, index) => { entry[locale] = row[index]; });
  copyCatalog[row[0]] = entry;
}

